insert into public.posts (student_id, category, title, body, thumb_url, created_at) values (
  'user_090406',
  '크리에이터 워크숍',
  '1강',
  '<div class="margin-top-xxl _comment_body_m202202288548544876283"><p style="text-align:left;"><img class="fr-dii" src="/mirror/a/cb520e23f79b98f4.jpeg" alt="1e7406ca4080f.jpeg" /></p><p style="text-align:left;"><img class="fr-dii" src="/mirror/a/72267c6c7dc4ff32.jpeg" alt="f7c0b72481a8e.jpeg" /></p><p style="text-align:left;"><img class="fr-dii" src="/mirror/a/443a26a8ae3a91b6.jpeg" alt="e9bffbc41860e.jpeg" /></p><p><br /></p><p><br /></p><p style="text-align:left;"><strong><span style="font-size:16px;"><em>Class Review in one sentence</em></span></strong></p><p style="text-align:justify;"><span style="font-size:18px;">준원이는 오늘 기획의 목표 설정과 개념, 그리고 앞으로의 활용 방향에 대해 학습하였습니다. 구체적인 목표를 설정하는 결단력과 이성적인 사고로 정리한 정보처리 능력이 뛰어났으며, 결과물로 이어지는 과정에서 사고를 더욱 확장해 나가는 모습이 인상적이었습니다. 그에 따른 사고의 깊이와 탄탄함이 돋보였습니다.</span></p><p style="text-align:justify;line-height:2;"><br /></p><p style="text-align:justify;line-height:2;"><br /></p><p style="text-align:right;"><span style="font-size:13px;">크리에이터 워크숍 3강 1/3 (토) 12:00</span></p><p style="text-align:right;line-height:1;"><span style="font-size:13px;">Responsible Instructor. </span><span style="font-size:14px;"><strong>홍채아</strong></span></p><p style="text-align:right;line-height:1;"><br /></p><p style="text-align:right;line-height:1;"><br /></p><p style="text-align:right;line-height:1;"><br /></p><hr /><p style="text-align:center;line-height:1;"><br /></p><p style="text-align:center;line-height:1;"><br /></p><p style="text-align:center;line-height:1;"><span style="font-size:16px;"><strong><span style="color:rgb(50,71,233);">Affinity Universe</span></strong></span></p><p style="text-align:center;line-height:1;"><span style="font-size:14px;">Creator Workshop Course.</span></p><p style="text-align:center;line-height:1;"><br /></p><p style="text-align:center;line-height:1;"><br /></p><p style="text-align:left;"><br /></p></div>
<div class="file_area"></div>',
  '/mirror/a/94ba0f12728e01ff.jpeg',
  '2026-01-03 00:13:00+09'
);
